import React, { useState, useContext, useEffect } from "react";
import { NavLink, useNavigate, useLocation, Link } from "react-router-dom";
import {
  Menu,
  X,
  LogOut,
  LayoutDashboard,
  Sparkles,
  ShieldCheck,
  Inbox,
} from "lucide-react";
import { AuthContext } from "../Context/AuthContext";
import logo from "../images/logo.png";
import EnrollmentModal from "./EnrollmentModal";
import api from "../api/axios";

const Navbar = () => {
  const { isAuth, user, logoutUser } = useContext(AuthContext);
  const navigate = useNavigate();
  const location = useLocation();
  const [isOpen, setIsOpen] = useState(false);
  const [enrollModalOpen, setEnrollModalOpen] = useState(false);
  const [pendingInquiriesCount, setPendingInquiriesCount] = useState(0);

  const isAdmin = isAuth && (user?.role === "ADMIN" || user?.role === "SUPER_ADMIN");
  const isOnAdminPage = location.pathname.startsWith("/admin");

  // Fetch pending inquiries count for admin notification indicator
  useEffect(() => {
    if (isAdmin) {
      const fetchInquiryCount = async () => {
        try {
          const res = await api.get("/enrollments");
          if (res.data.success) {
            const pending = res.data.data.filter((e) => e.status === "PENDING").length;
            setPendingInquiriesCount(pending);
          }
        } catch (err) {
          // silent fallback
        }
      };
      fetchInquiryCount();
    }
  }, [isAdmin, location.pathname]);

  const navLinks = [
    { to: "/", label: "Home" },
    { to: "/courses", label: "Courses & Classes" },
    { to: "/teachers", label: "Faculty" },
    { to: "/about", label: "About Us" },
  ];

  const getDashboardPath = () => {
    if (!user) return "/login";
    switch (user.role) {
      case "ADMIN":
      case "SUPER_ADMIN":
        return "/admin";
      case "TEACHER":
        return "/teacher";
      case "PARENT":
        return "/parent";
      case "STUDENT":
        return "/student";
      default:
        return "/";
    }
  };

  const handleLogout = () => {
    logoutUser();
    navigate("/");
    setIsOpen(false);
  };

  return (
    <>
      <header className="bg-[#d49539] sticky top-0 z-40 shadow-md">
        {/* Universal Top Navigation Header */}
        <div className="max-w-7xl mx-auto px-4 md:px-8 lg:px-12 py-3 flex items-center justify-between h-[82px]">
          {/* Logo & Institute Brand Name */}
          <Link
            to="/"
            className="flex items-center gap-3 cursor-pointer group"
          >
            <img src={logo} alt="Success Mentor logo" className="h-[52px] object-contain transition-transform group-hover:scale-105" />
            <div className="text-left">
              <span className="font-black text-lg md:text-xl text-[#304b62] block leading-tight tracking-tight">
                Success Mentor
              </span>
              <span className="text-[11px] font-bold text-white tracking-wide block leading-none">
                Premier Coaching Institute
              </span>
            </div>
          </Link>

          {/* Consistent Desktop Navigation Links */}
          <nav className="hidden md:flex items-center gap-1 lg:gap-5">
            {navLinks.map((link) => {
              const isActive = location.pathname === link.to;
              return (
                <NavLink
                  to={link.to}
                  key={link.to}
                  className={`relative py-2 px-3 font-bold text-sm lg:text-base transition-colors ${
                    isActive ? "text-[#304b62] font-black" : "text-[#304b62]/90 hover:text-[#304b62]"
                  }`}
                >
                  {link.label}
                  {isActive && (
                    <span className="absolute bottom-[-6px] left-0 right-0 h-[4px] bg-[#304b62] rounded-t-md" />
                  )}
                </NavLink>
              );
            })}
          </nav>

          {/* Right Action / Auth & Profile Buttons */}
          <div className="hidden md:flex items-center gap-3">
            {isAuth ? (
              <div className="flex items-center gap-2.5">
                {/* Admin Quick Inquiry Badge */}
                {isAdmin && pendingInquiriesCount > 0 && (
                  <Link
                    to="/admin?tab=ENROLLMENTS"
                    title={`${pendingInquiriesCount} Pending Admission Inquiries`}
                    className="bg-white/20 hover:bg-white/30 text-[#304b62] p-2 rounded-xl text-xs flex items-center gap-1.5 transition-colors relative"
                  >
                    <Inbox size={18} />
                    <span className="bg-[#304b62] text-white text-[10px] font-black px-1.5 py-0.5 rounded-full">
                      {pendingInquiriesCount}
                    </span>
                  </Link>
                )}

                {/* Role-Based Dashboard Pill */}
                <Link
                  to={getDashboardPath()}
                  className={`px-4 py-2 rounded-xl text-xs flex items-center gap-2.5 shadow-sm transition-all ${
                    isOnAdminPage
                      ? "bg-[#304b62] text-white ring-2 ring-white/30"
                      : "bg-[#304b62] hover:bg-[#253b4e] text-white"
                  }`}
                >
                  {isAdmin ? (
                    <ShieldCheck size={16} className="text-[#d49539]" />
                  ) : (
                    <LayoutDashboard size={16} className="text-[#d49539]" />
                  )}
                  <div className="text-left">
                    <span className="block text-[10px] text-[#f6d6a0] uppercase tracking-wider font-black leading-none">
                      {isAdmin ? "Admin Portal" : user?.role}
                    </span>
                    <span className="block font-bold truncate max-w-[120px] leading-tight">
                      {user?.name || "User"}
                    </span>
                  </div>
                </Link>

                {/* Logout Button */}
                <button
                  onClick={handleLogout}
                  title="Sign Out"
                  className="p-2.5 bg-white/20 hover:bg-white/30 text-[#304b62] rounded-xl transition-colors"
                >
                  <LogOut size={18} />
                </button>
              </div>
            ) : (
              <div className="flex items-center gap-3">
                <button
                  onClick={() => navigate("/login")}
                  className="bg-white/20 hover:bg-white/30 text-[#304b62] font-extrabold px-4 py-2 rounded-xl text-sm transition-colors"
                >
                  Log In
                </button>
                <button
                  onClick={() => setEnrollModalOpen(true)}
                  className="bg-[#304b62] hover:bg-[#253b4e] text-white font-bold px-5 py-2.5 rounded-xl transition-colors shadow-md text-sm flex items-center gap-1.5"
                >
                  <Sparkles size={15} /> Admission Now
                </button>
              </div>
            )}
          </div>

          {/* Mobile Hamburger Button */}
          <button
            onClick={() => setIsOpen(!isOpen)}
            className="md:hidden p-2 text-[#304b62] hover:bg-black/10 rounded-lg focus:outline-none"
            aria-label="Toggle Navigation Menu"
          >
            {isOpen ? <X size={26} /> : <Menu size={26} />}
          </button>
        </div>

        {/* Mobile Drawer */}
        {isOpen && (
          <div className="fixed inset-0 z-50 md:hidden flex justify-end animate-fadeIn">
            <div className="fixed inset-0 bg-black/50" onClick={() => setIsOpen(false)} />
            <div className="relative w-80 bg-[#d49539] h-full p-6 shadow-2xl flex flex-col z-10 space-y-4 overflow-y-auto">
              <div className="flex justify-between items-center pb-3 border-b border-[#304b62]/20">
                <div>
                  <span className="font-black text-xl text-[#304b62] block">Success Mentor</span>
                  <span className="text-xs font-bold text-white">Premier Institute</span>
                </div>
                <button onClick={() => setIsOpen(false)} className="p-1 text-[#304b62]">
                  <X size={24} />
                </button>
              </div>

              {/* Mobile Links */}
              <div className="flex flex-col gap-2">
                {navLinks.map((link) => (
                  <NavLink
                    to={link.to}
                    key={link.to}
                    onClick={() => setIsOpen(false)}
                    className="font-bold text-base py-2.5 px-3 rounded-lg text-[#304b62] hover:bg-black/10"
                  >
                    {link.label}
                  </NavLink>
                ))}

                {isAuth ? (
                  <div className="pt-4 border-t border-[#304b62]/20 space-y-2">
                    <Link
                      to={getDashboardPath()}
                      onClick={() => setIsOpen(false)}
                      className="bg-[#304b62] text-white font-bold py-2.5 px-4 rounded-xl text-center text-sm flex items-center justify-center gap-2"
                    >
                      {isAdmin ? <ShieldCheck size={16} className="text-[#d49539]" /> : <LayoutDashboard size={16} />}
                      <span>{isAdmin ? "Open Admin Portal" : "Open Dashboard"}</span>
                    </Link>
                    <button
                      onClick={handleLogout}
                      className="w-full bg-white/20 text-[#304b62] font-bold py-2.5 px-4 rounded-xl text-center text-sm flex items-center justify-center gap-1.5"
                    >
                      <LogOut size={16} /> Sign Out
                    </button>
                  </div>
                ) : (
                  <div className="pt-4 border-t border-[#304b62]/20 space-y-2">
                    <button
                      onClick={() => {
                        navigate("/login");
                        setIsOpen(false);
                      }}
                      className="w-full bg-white/20 text-[#304b62] font-bold py-2.5 rounded-xl text-sm"
                    >
                      Log In
                    </button>
                    <button
                      onClick={() => {
                        setEnrollModalOpen(true);
                        setIsOpen(false);
                      }}
                      className="w-full bg-[#304b62] text-white font-bold py-2.5 rounded-xl text-sm flex items-center justify-center gap-1.5"
                    >
                      <Sparkles size={16} /> Admission Now
                    </button>
                  </div>
                )}
              </div>
            </div>
          </div>
        )}
      </header>

      {/* Global Enrollment Modal */}
      <EnrollmentModal
        isOpen={enrollModalOpen}
        onClose={() => setEnrollModalOpen(false)}
        preselectedClass={10}
        preselectedCourse="General Admission Inquiry"
      />
    </>
  );
};

export default Navbar;
